from datetime import datetime, timezone

def normalize_timestamp(value):
    try:
        # Parse the ISO timestamp string
        dt = datetime.fromisoformat(value)
    except ValueError:
        raise ValueError("Invalid ISO timestamp format")

    # Check if the datetime is naive (without timezone)
    if dt.tzinfo is None:
        raise ValueError("Timestamp must be aware or have a timezone specified")

    # If the datetime is naive, try to parse again with timezone-aware parsing
    try:
        dt = datetime.fromisoformat(value + "Z")
    except ValueError:
        raise ValueError("Timestamp must be aware or have a timezone specified")

    # Ensure the datetime is in UTC
    if dt.tzinfo is not None and dt.tzinfo.utcoffset(dt) is not None:
        dt = dt.astimezone(timezone.utc)

    return dt

def retry(call, attempts):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    for i in range(attempts):
        try:
            result = call()
            return result
        except RuntimeError:
            if i == attempts - 1:
                raise

def retry(call, attempts):
    """
    Retry a function call up to 'attempts' times until it succeeds.
    If all attempts fail, return None.
    """
    for _ in range(attempts):
        try:
            result = call()
            return result
        except Exception as e:
            continue
    return None

